  "The payment review was saved, but this older request has no submitting-owner user ID to notify.": "ការពិនិត្យការបង់ប្រាក់បានរក្សាទុក ប៉ុន្តែសំណើចាស់នេះគ្មាន ID អ្នកប្រើរបស់ម្ចាស់ដែលបានដាក់ស្នើ ដើម្បីជូនដំណឹងទេ។",
