  "Ask the business owner to renew or reactivate the TENH POS subscription. Your account can be used again when access is restored.": "ស្នើឱ្យម្ចាស់អាជីវកម្មបន្ត ឬបើកការជាវ TENH POS ឡើងវិញ។ អ្នកអាចប្រើគណនីឡើងវិញបាន នៅពេលសិទ្ធិចូលប្រើត្រូវបានស្ដារ។",
  "You no longer have access": "អ្នកលែងមានសិទ្ធិចូលប្រើ",
  "The business owner removed your account from this TENH POS business.": "ម្ចាស់អាជីវកម្មបានដកគណនីរបស់អ្នកចេញពីអាជីវកម្ម TENH POS នេះ។",
  "If you believe this was a mistake, contact the business owner. Your TENH login may still be used for another business you belong to.": "ប្រសិនបើអ្នកគិតថាមានកំហុស សូមទាក់ទងម្ចាស់អាជីវកម្ម។ គណនី TENH របស់អ្នកនៅតែអាចប្រើជាមួយអាជីវកម្មផ្សេងដែលអ្នកជាសមាជិក។",
  "Your business access is disabled": "សិទ្ធិចូលប្រើអាជីវកម្មរបស់អ្នកត្រូវបានបិទ",
  "Your membership is currently disabled for this TENH POS business.": "សមាជិកភាពរបស់អ្នកត្រូវបានបិទសម្រាប់អាជីវកម្ម TENH POS នេះ។",
  "Contact the business owner or administrator if your access should be restored.": "សូមទាក់ទងម្ចាស់អាជីវកម្ម ឬអ្នកគ្រប់គ្រង ប្រសិនបើត្រូវស្ដារសិទ្ធិចូលប្រើរបស់អ្នក។",
  "Your seat is paused": "សិទ្ធិអ្នកប្រើរបស់អ្នកបានផ្អាក",
  "Your access was paused because the business subscription no longer has enough active user seats.": "សិទ្ធិចូលប្រើរបស់អ្នកបានផ្អាក ព្រោះការជាវរបស់អាជីវកម្មលែងមានចំនួនអ្នកប្រើសកម្មគ្រប់គ្រាន់។",
  "The owner can upgrade the subscription or free another seat, then reactivate your user.": "ម្ចាស់អាចដំឡើងគម្រោង ឬធ្វើឱ្យមានកន្លែងទំនេរសម្រាប់អ្នកប្រើ រួចបើកគណនីរបស់អ្នកឡើងវិញ។",
  "Owner setup required": "ត្រូវការការរៀបចំពីម្ចាស់",
  "This business is waiting for the owner to choose a TENH POS subscription or start the 7-day free trial.": "អាជីវកម្មនេះកំពុងរង់ចាំម្ចាស់ជ្រើសរើសការជាវ TENH POS ឬចាប់ផ្ដើមការសាកល្បងឥតគិតថ្លៃ 7 ថ្ងៃ។",
  "Team access will become available only after the owner activates an eligible paid team plan.": "សិទ្ធិចូលប្រើរបស់ក្រុមនឹងមាន លុះត្រាតែម្ចាស់បើកគម្រោងក្រុមបង់ថ្លៃដែលមានសិទ្ធិ។",
  "Business access unavailable": "មិនអាចចូលប្រើអាជីវកម្មបាន",
