  "The business may have been deleted or your membership may have been removed. Contact the business owner if you need access again.": "អាជីវកម្មអាចត្រូវបានលុប ឬសមាជិកភាពរបស់អ្នកអាចត្រូវបានដកចេញ។ សូមទាក់ទងម្ចាស់អាជីវកម្ម បើអ្នកត្រូវការចូលប្រើឡើងវិញ។",
  "Business account disabled": "គណនីអាជីវកម្មត្រូវបានបិទ",
  "Access to this TENH POS business has been disabled.": "សិទ្ធិចូលប្រើអាជីវកម្ម TENH POS នេះត្រូវបានបិទ។",
  "Contact the business owner or TENH POS administrator if the business should be reactivated.": "សូមទាក់ទងម្ចាស់អាជីវកម្ម ឬអ្នកគ្រប់គ្រង TENH POS ប្រសិនបើត្រូវបើកអាជីវកម្មឡើងវិញ។",
