  "Unable to send the reset link right now. Please try again shortly.": "មិនអាចផ្ញើតំណកំណត់ពាក្យសម្ងាត់ឡើងវិញបាននៅពេលនេះទេ។ សូមព្យាយាមម្តងទៀតបន្តិចទៀត។",
