  "Your account is not connected to an active TENH POS business. The business may have been deleted, your access may have been removed, or no business has been assigned yet.": "គណនីរបស់អ្នកមិនបានភ្ជាប់នឹងអាជីវកម្ម TENH POS សកម្មទេ។ អាជីវកម្មអាចត្រូវបានលុប សិទ្ធិចូលប្រើរបស់អ្នកអាចត្រូវបានដកចេញ ឬមិនទាន់បានចាត់តាំងអាជីវកម្ម។",
  "Fast POS checkout": "គិតលុយរហ័សជាមួយ POS",
  "Sell in store with products, variants, stock and order history connected to one business.": "លក់ក្នុងហាង ដោយភ្ជាប់ផលិតផល ជម្រើសផលិតផល ស្តុក និងប្រវត្តិការបញ្ជាទិញនឹងអាជីវកម្មតែមួយ។",
  "Built-in online store": "ហាងអនឡាញដែលមានស្រាប់ក្នុងប្រព័ន្ធ",
  "Publish a customer-facing storefront on your TENH subdomain without moving the admin dashboard.": "ផ្សព្វផ្សាយហាងសម្រាប់អតិថិជននៅលើ subdomain TENH របស់អ្នក ដោយមិនផ្លាស់ទីផ្ទាំងគ្រប់គ្រង។",
  "Let customers scan, browse products or menus, and place an online order from their phone.": "ឱ្យអតិថិជនស្កេន មើលផលិតផល ឬម៉ឺនុយ ហើយបញ្ជាទិញអនឡាញពីទូរស័ព្ទ។",
  "Inventory that stays together": "ស្តុកទំនិញដែលភ្ជាប់គ្នា",
  "Track stock, low-stock levels, product variants, transfers and inventory activity from one place.": "តាមដានស្តុក កម្រិតស្តុកទាប ជម្រើសផលិតផល ការផ្ទេរ និងសកម្មភាពស្តុកនៅកន្លែងតែមួយ។",
  "Customers & staff": "អតិថិជន និងបុគ្គលិក",
  "Keep customer records while owners, admins, managers, cashiers and staff work in the same app.": "រក្សាព័ត៌មានអតិថិជន ខណៈម្ចាស់ អ្នកគ្រប់គ្រង អ្នកគ្រប់គ្រងហាង អ្នកគិតលុយ និងបុគ្គលិកធ្វើការក្នុងកម្មវិធីតែមួយ។",
  "Reports & control": "របាយការណ៍ និងការគ្រប់គ្រង",
  "Follow sales, products, customers and operational activity with reports built into the dashboard.": "តាមដានការលក់ ផលិតផល អតិថិជន និងសកម្មភាពប្រតិបត្តិការ តាមរបាយការណ៍ក្នុងផ្ទាំងគ្រប់គ្រង។",
  "Products & variants": "ផលិតផល និងជម្រើសផលិតផល",
  "Fashion sizes and colours, shoes, standard products and mode-specific catalog workflows.": "ទំហំ និងពណ៌សម្លៀកបំពាក់ ស្បែកជើង ផលិតផលស្តង់ដារ និងការងារបញ្ជីផលិតផលតាមប្រភេទអាជីវកម្ម។",
  "Stock levels, low-stock alerts, barcode workflows and branch-aware inventory operations.": "កម្រិតស្តុក ការជូនដំណឹងស្តុកទាប ការងារបាកូដ និងប្រតិបត្តិការស្តុកតាមសាខា។",
  "Maintain supplier records and connect purchasing to the products you actually receive.": "រក្សាព័ត៌មានអ្នកផ្គត់ផ្គង់ និងភ្ជាប់ការទិញចូលនឹងផលិតផលដែលអ្នកទទួលជាក់ស្ដែង។",
  "Create purchase orders, track incoming quantities and receive purchased stock into inventory.": "បង្កើតបញ្ជាទិញពីអ្នកផ្គត់ផ្គង់ តាមដានបរិមាណទំនិញចូល និងទទួលទំនិញដែលបានទិញចូលក្នុងស្តុក។",
  "Keep return activity connected to orders and your operational history.": "ភ្ជាប់សកម្មភាពត្រឡប់ទំនិញនឹងការបញ្ជាទិញ និងប្រវត្តិប្រតិបត្តិការរបស់អ្នក។",
  "In-store and online orders stay connected to the same TENH business workspace.": "ការបញ្ជាទិញក្នុងហាង និងអនឡាញភ្ជាប់នឹងកន្លែងធ្វើការអាជីវកម្ម TENH តែមួយ។",
