  "Your pending registration email was not found. Please return to registration and try again.": "រកមិនឃើញអ៊ីមែលចុះឈ្មោះដែលកំពុងរង់ចាំរបស់អ្នកទេ។ សូមត្រឡប់ទៅទំព័រចុះឈ្មោះ ហើយព្យាយាមម្តងទៀត។",
