  "Unable to create your account. Check the Supabase Auth logs for the exact database error.": "មិនអាចបង្កើតគណនីរបស់អ្នកបានទេ។ សូមពិនិត្យកំណត់ហេតុ Supabase Auth ដើម្បីដឹងកំហុសមូលដ្ឋានទិន្នន័យច្បាស់លាស់។",
  "Unable to continue with {0}. Please try again.": "មិនអាចបន្តជាមួយ {0} បានទេ។ សូមព្យាយាមម្តងទៀត។",
