  "Your password-reset session has expired.": "វគ្គកំណត់ពាក្យសម្ងាត់ឡើងវិញរបស់អ្នកបានផុតកំណត់។",
  "Your password has been updated successfully.": "ពាក្យសម្ងាត់របស់អ្នកបានធ្វើបច្ចុប្បន្នភាពដោយជោគជ័យ។",
