  "ABA PayWay live payments are disabled. Set PAYWAY_LIVE_ENABLED=true only after production approval.": "ការទូទាត់ពិត ABA PayWay ត្រូវបានបិទ។ កំណត់ PAYWAY_LIVE_ENABLED=true តែក្រោយទទួលការអនុម័តសម្រាប់ប្រព័ន្ធពិត។",
