  "ABA PayWay requires a public whitelisted TENH_APP_URL. Use your HTTPS app domain instead of localhost.": "ABA PayWay ត្រូវការ TENH_APP_URL សាធារណៈដែលបានអនុញ្ញាត។ ប្រើដែន HTTPS របស់កម្មវិធីជំនួស localhost។",
