  "Owner only · Current branch by default · No 10,000-row cap. Includes saved settings and file references. Uploaded file contents, passwords, security tokens and platform administration are excluded. Large exports may take longer; failures never download a partial file.": "សម្រាប់ម្ចាស់ប៉ុណ្ណោះ · សាខាបច្ចុប្បន្នជាលំនាំដើម · មិនកំណត់ត្រឹម 10,000 ជួរដេកទេ។ រួមបញ្ចូលការកំណត់ដែលបានរក្សាទុក និងតំណយោងឯកសារ។ មិនរួមបញ្ចូលមាតិកាឯកសារដែលបានផ្ទុកឡើង ពាក្យសម្ងាត់ ថូខិនសុវត្ថិភាព និងការគ្រប់គ្រងវេទិកាទេ។ ការនាំចេញធំអាចចំណាយពេលយូរ។ ប្រសិនបើបរាជ័យ ឯកសារមិនពេញលេញនឹងមិនត្រូវបានទាញយកទេ។",
