  "Recommended now: the system print dialog. Automatic device discovery and direct printing require a separately configured desktop print connector, such as QZ Tray.": "ណែនាំឱ្យប្រើប្រអប់បោះពុម្ពរបស់ប្រព័ន្ធ។ ការរកឧបករណ៍ដោយស្វ័យប្រវត្តិ និងការបោះពុម្ពផ្ទាល់ត្រូវការកម្មវិធីភ្ជាប់បោះពុម្ពដែលបានកំណត់ដាច់ដោយឡែក ដូចជា QZ Tray។",
