  "JPG, PNG or WebP, up to 5 MB. Saved with your name when you click Save Changes. Also appears on mobile.": "JPG, PNG ឬ WebP រហូតដល់ 5 MB។ រក្សាទុកជាមួយឈ្មោះពេលអ្នកចុចរក្សាទុកការផ្លាស់ប្តូរ ហើយបង្ហាញលើទូរសព្ទផងដែរ។",
  "Standard Receipt · customize your images and text with a live preview.": "បង្កាន់ដៃស្តង់ដារ · កែតម្រូវរូបភាព និងអត្ថបទដោយមើលសាកល្បងភ្លាមៗ។",
