  "Print text": "អត្ថបទបោះពុម្ព",
  "Text size applies to receipts, barcode labels and shipping labels for this branch.": "ទំហំអក្សរអនុវត្តចំពោះបង្កាន់ដៃ ស្លាកបាកូដ និងស្លាកដឹកជញ្ជូនសម្រាប់សាខានេះ។",
