  "Center": "កណ្ដាល",
  "Receipt logo": "និមិត្តសញ្ញាបង្កាន់ដៃ",
  "This logo is for receipts only. Your storefront logo is not changed. Uploaded logos are public branding assets.": "ឡូហ្គោនេះសម្រាប់បង្កាន់ដៃតែប៉ុណ្ណោះ។ ឡូហ្គោហាងអនឡាញមិនត្រូវបានប្តូរទេ។ ឡូហ្គោដែលផ្ទុកឡើងជារូបភាពម៉ាកសាធារណៈ។",
  "Recommended logo: 600 × 300 px. Prints up to 40 × 20 mm. PNG, JPEG or WebP, max 750 KB.": "ឡូហ្គោដែលណែនាំ៖ 600 × 300 px។ បោះពុម្ពរហូតដល់ 40 × 20 mm។ PNG, JPEG ឬ WebP អតិបរមា 750 KB។",
  "Upload PNG / JPEG / WebP · max 750 KB": "ផ្ទុក PNG / JPEG / WebP ឡើង · អតិបរមា 750 KB",
  "Remove receipt logo": "ដកឡូហ្គោបង្កាន់ដៃចេញ",
  "Receipt QR code": "លេខកូដ QR នៃបង្កាន់ដៃ",
  "Upload the original QR image, preferably a 1000 × 1000 px PNG. Target size: 80 × 80 mm, automatically reduced to fit the receipt width and margins. Keep a clear white border at least four QR squares wide on every side. PNG, JPEG or WebP, max 750 KB.": "ផ្ទុករូបភាព QR ដើមឡើង ដោយគួរប្រើ PNG ទំហំ 1000 × 1000 px។ ទំហំគោលដៅ៖ 80 × 80 mm ហើយនឹងបង្រួមដោយស្វ័យប្រវត្តិឱ្យសមនឹងទទឹង និងគែមបង្កាន់ដៃ។ ទុកគែមសច្បាស់យ៉ាងតិចទទឹងស្មើការ៉េ QR ចំនួនបួននៅគ្រប់ជ្រុង។ PNG, JPEG ឬ WebP អតិបរមា 750 KB។",
  "For payments, use the original merchant QR downloaded from your bank. Upload the QR itself with its white border, not a photo or a full poster. Print at 100% scale, then test the paper QR with your phone before using it.": "សម្រាប់ការទូទាត់ ប្រើ QR អាជីវករដើមដែលបានទាញយកពីធនាគារ។ ផ្ទុករូប QR ជាមួយគែមសរបស់វាឡើង ជំនួសរូបថត ឬផ្ទាំងផ្សព្វផ្សាយទាំងមូល។ បោះពុម្ពនៅមាត្រដ្ឋាន 100% រួចសាកល្បងស្កេន QR លើក្រដាសដោយទូរសព្ទមុនប្រើ។",
