  "ABA PayWay could not safely close the current transaction yet. TENH kept it locked to prevent duplicate payment.": "ABA PayWay មិនទាន់អាចបិទប្រតិបត្តិការបច្ចុប្បន្នដោយសុវត្ថិភាពបានទេ។ TENH រក្សាវាឱ្យចាក់សោ ដើម្បីការពារការទូទាត់ស្ទួន។",
  "TENH could not confirm the ABA PayWay status right now. No payment method was changed.": "TENH មិនអាចបញ្ជាក់ស្ថានភាព ABA PayWay នៅពេលនេះបានទេ។ គ្មានវិធីទូទាត់ត្រូវបានប្តូរទេ។",
  "Reopening checkout uses the same payment request.": "ការបើកទំព័រទូទាត់ឡើងវិញប្រើសំណើទូទាត់ដដែល។",
