  "Manual Bank Transfer is selected. Click the Manual payment card again to reopen the transfer and receipt popup.": "បានជ្រើសការផ្ទេរតាមធនាគារដោយដៃ។ ចុចកាតការទូទាត់ដោយដៃម្តងទៀត ដើម្បីបើកប្រអប់ផ្ទេរប្រាក់ និងបង្កាន់ដៃឡើងវិញ។",
