  "Optional. Without a selection, TENH POS protects the Owner and Main Branch, keeps the oldest allowed records, and disables the newest excess users and branches automatically.": "មិនចាំបាច់ជ្រើសទេ។ បើមិនជ្រើស TENH POS នឹងការពារម្ចាស់ និងសាខាចម្បង រក្សាកំណត់ត្រាចាស់ៗត្រឹមដែនកំណត់ និងបិទអ្នកប្រើប្រាស់/សាខាថ្មីដែលលើសកំណត់ដោយស្វ័យប្រវត្តិ។",
