  "will be disabled. Owner and Main Branch stay protected. Nothing is deleted, and you can change the selection later within your plan limits.": "នឹងត្រូវបិទដំណើរការ។ ម្ចាស់ និងសាខាចម្បងនៅតែត្រូវបានការពារ។ គ្មានទិន្នន័យត្រូវបានលុបទេ ហើយអ្នកអាចប្តូរជម្រើសនៅពេលក្រោយក្នុងដែនកំណត់គម្រោង។",
  "Go back": "ត្រឡប់ក្រោយ",
  "I’m okay with that": "ខ្ញុំយល់ព្រម",
  "Our team is verifying your payment details.": "ក្រុមការងារយើងកំពុងផ្ទៀងផ្ទាត់ព័ត៌មានទូទាត់របស់អ្នក។",
