  "Only the business owner can purchase or change the subscription plan.": "មានតែម្ចាស់អាជីវកម្មប៉ុណ្ណោះដែលអាចទិញ ឬប្តូរគម្រោងជាវបាន។",
  "Reactivate your latest subscription only": "បើកគម្រោងជាវចុងក្រោយឡើងវិញតែប៉ុណ្ណោះ",
  "Your plan and capacity stay the same:": "គម្រោង និងចំនួនអនុញ្ញាតរបស់អ្នកនៅដដែល៖",
  ". Choose the new billing term, then continue to payment.": "។ ជ្រើសរយៈពេលគិតថ្លៃថ្មី រួចបន្តទៅការទូទាត់។",
  "Choose a different plan instead": "ជ្រើសគម្រោងផ្សេង",
