  "Your business is already created. Paid checkout does not change your business ID, products, store URL, or settings.": "អាជីវកម្មរបស់អ្នកត្រូវបានបង្កើតរួចហើយ។ ការទូទាត់មិនប្តូរ ID អាជីវកម្ម ផលិតផល តំណហាង ឬការកំណត់របស់អ្នកទេ។",
  "The free trial is not available for this account. You can continue with any paid plan below.": "គណនីនេះមិនអាចសាកល្បងឥតគិតថ្លៃបានទេ។ អ្នកអាចបន្តជាមួយគម្រោងបង់ប្រាក់ណាមួយខាងក្រោម។",
  "Your 7-day free trial is already active.": "ការសាកល្បងឥតគិតថ្លៃ 7 ថ្ងៃរបស់អ្នកកំពុងដំណើរការរួចហើយ។",
  "Continue to dashboard": "បន្តទៅផ្ទាំងគ្រប់គ្រង",
