  "Your current plan stays active until expiry. If the new plan has lower limits, TENH POS protects the Owner and Main Branch and disables the newest excess users or branches.": "គម្រោងបច្ចុប្បន្ននៅតែសកម្មរហូតដល់ផុតកំណត់។ បើគម្រោងថ្មីមានដែនកំណត់ទាបជាង TENH POS នឹងការពារម្ចាស់ និងសាខាចម្បង ហើយបិទអ្នកប្រើប្រាស់ ឬសាខាថ្មីដែលលើសកំណត់។",
  "Current paid access stays unchanged until": "សិទ្ធិប្រើប្រាស់ដែលបានបង់បច្ចុប្បន្ននៅដដែលរហូតដល់",
  "At that time, this plan becomes active. Excess users and branches are disabled, never deleted. Owner and Main Branch stay protected.": "នៅពេលនោះ គម្រោងនេះនឹងចាប់ផ្តើម។ អ្នកប្រើប្រាស់ និងសាខាលើសកំណត់នឹងត្រូវបិទដំណើរការ ដោយមិនលុបទេ។ ម្ចាស់ និងសាខាចម្បងនៅតែត្រូវបានការពារ។",
  "If you skip selection, TENH POS keeps the oldest allowed users and branches after the protected Owner/Main Branch, so the newest excess records are disabled automatically.": "បើមិនជ្រើស TENH POS នឹងរក្សាអ្នកប្រើប្រាស់ និងសាខាចាស់ៗត្រឹមដែនកំណត់ បន្ទាប់ពីការពារម្ចាស់/សាខាចម្បង ហើយបិទកំណត់ត្រាថ្មីដែលលើសកំណត់ដោយស្វ័យប្រវត្តិ។",
