  "Add a note for this order…": "បន្ថែមចំណាំសម្រាប់ការបញ្ជាទិញនេះ…",
  "The order is already cancelled. Stock will not be restored twice.": "ការបញ្ជាទិញត្រូវបានបោះបង់រួចហើយ។ ស្តុកនឹងមិនត្រូវបានស្តារពីរដងទេ។",
  "The order will first be cancelled using the existing stock-restoration procedure.": "ការបញ្ជាទិញនឹងត្រូវបានបោះបង់ជាមុន ដោយប្រើនីតិវិធីស្តារស្តុកដែលមានស្រាប់។",
