  "Select at least one item to return.": "ជ្រើសរើសមុខទំនិញត្រូវត្រឡប់យ៉ាងតិចមួយ។",
  "Invalid return item data.": "ទិន្នន័យមុខទំនិញត្រឡប់មិនត្រឹមត្រូវ។",
  "Each order item can only appear once in a return.": "មុខទំនិញនីមួយៗអាចមានតែម្តងក្នុងការត្រឡប់ទំនិញ។",
  "Apply the register accounting and operating branch migrations before recording refunds.": "អនុវត្តឯកសារធ្វើបច្ចុប្បន្នភាពគណនេយ្យបញ្ជរប្រាក់ និងសាខាប្រតិបត្តិការ មុនពេលកត់ត្រាប្រាក់សង។",
  "The return was created, but no return ID was returned.": "ការត្រឡប់ទំនិញត្រូវបានបង្កើត ប៉ុន្តែមិនបានត្រឡប់លេខសម្គាល់ទេ។",
  "Returned products for order {0}": "ផលិតផលត្រឡប់សម្រាប់ការបញ្ជាទិញ {0}",
