  "Return committed; cache refresh failed. Do not repeat the refund.": "ការត្រឡប់ទំនិញបានរក្សាទុក ប៉ុន្តែការផ្ទុកឃ្លាំងទិន្នន័យបណ្តោះអាសន្នឡើងវិញបានបរាជ័យ។ កុំសងប្រាក់ម្តងទៀត។",
  "Return created successfully.": "ការត្រឡប់ទំនិញត្រូវបានបង្កើតដោយជោគជ័យ។",
