  "Products, stock and held orders refreshed.": "ផលិតផល ស្តុក និងការបញ្ជាទិញផ្អាកបានផ្ទុកឡើងវិញ។",
  "Choose a branch before adding products to an order.": "ជ្រើសរើសសាខា មុនពេលបន្ថែមផលិតផលទៅការបញ្ជាទិញ។",
  "{0} added to the current order.": "បានបន្ថែម {0} ទៅការបញ្ជាទិញបច្ចុប្បន្ន។",
