  "{0} is unavailable; remove it first.": "មិនមាន {0} ទេ។ សូមដកចេញជាមុន។",
  "Cart prices updated. Review the total before taking payment.": "តម្លៃក្នុងកន្ត្រកបានកែ។ សូមពិនិត្យចំនួនសរុប មុនពេលទទួលប្រាក់។",
  "Enter a label for the held order.": "បញ្ចូលឈ្មោះសម្រាប់ការបញ្ជាទិញផ្អាក។",
  "Review this cart.": "ពិនិត្យកន្ត្រកនេះ។",
