  "Held order resumed with its size/color, discount, shipping and split draft. Current prices and stock were loaded. Review totals and confirm payment again.": "បានបន្តការបញ្ជាទិញផ្អាក ជាមួយទំហំ/ពណ៌ ការបញ្ចុះតម្លៃ ការដឹកជញ្ជូន និងសេចក្តីព្រាងការបង់ប្រាក់បែងចែក។ តម្លៃ និងស្តុកបច្ចុប្បន្នបានផ្ទុកហើយ។ សូមពិនិត្យចំនួនសរុប និងបញ្ជាក់ការបង់ប្រាក់ម្តងទៀត។",
