  "This template changed since you opened it. Reload settings before saving.": "គំរូនេះបានផ្លាស់ប្តូរបន្ទាប់ពីអ្នកបើក។ ផ្ទុកការកំណត់ឡើងវិញមុនរក្សាទុក។",
