  "Current password is incorrect.": "ពាក្យសម្ងាត់បច្ចុប្បន្នមិនត្រឹមត្រូវ។",
  "Your password was saved, but other device sessions could not be signed out. Use Sign out other devices in Security settings to retry.": "បានរក្សាទុកពាក្យសម្ងាត់ ប៉ុន្តែមិនអាចចាកចេញពីគណនីលើឧបករណ៍ផ្សេងបានទេ។ ប្រើចាកចេញពីឧបករណ៍ផ្សេងក្នុងការកំណត់សុវត្ថិភាពដើម្បីសាកល្បងម្តងទៀត។",
  "Password changed successfully. Other device sessions were signed out.": "បានប្តូរពាក្យសម្ងាត់ដោយជោគជ័យ។ គណនីលើឧបករណ៍ផ្សេងត្រូវបានចាកចេញ។",
  "Password created successfully. You can now sign in with email and password.": "បានបង្កើតពាក្យសម្ងាត់ដោយជោគជ័យ។ ឥឡូវអ្នកអាចចូលគណនីដោយអ៊ីមែល និងពាក្យសម្ងាត់។",
