  "Type \"DELETE\" to confirm permanent account deletion.": "វាយ \"DELETE\" ដើម្បីបញ្ជាក់ការលុបគណនីជាអចិន្ត្រៃយ៍។",
  "A Super Admin account cannot delete itself from this page.": "គណនីអ្នកគ្រប់គ្រងជាន់ខ្ពស់មិនអាចលុបខ្លួនឯងពីទំព័រនេះបានទេ។",
  "Unable to inspect business users: {0}": "មិនអាចពិនិត្យអ្នកប្រើប្រាស់អាជីវកម្មបាន៖ {0}",
  "This business still has related data protected by a database constraint. Nothing else should be deleted until that relationship is corrected.": "អាជីវកម្មនេះនៅតែមានទិន្នន័យពាក់ព័ន្ធដែលការពារដោយលក្ខខណ្ឌមូលដ្ឋានទិន្នន័យ។ មិនត្រូវលុបអ្វីបន្ថែមទៀតទេ រហូតដល់កែទំនាក់ទំនងនោះ។",
