  "Your active business changed or this checkout page is stale. Reload plans before purchasing.": "អាជីវកម្មសកម្មបានប្តូរ ឬទំព័រទូទាត់នេះហួសបច្ចុប្បន្នភាព។ ផ្ទុកគម្រោងឡើងវិញមុនទិញ។",
  "Your subscription is no longer expired. Refresh Subscription to see its current status.": "គម្រោងជាវរបស់អ្នកលែងផុតកំណត់។ ផ្ទុកគម្រោងជាវឡើងវិញដើម្បីមើលស្ថានភាពបច្ចុប្បន្ន។",
  "Unable to load your current subscription. Please try again.": "មិនអាចផ្ទុកគម្រោងជាវបច្ចុប្បន្នបានទេ។ សូមសាកល្បងម្តងទៀត។",
  "Your previous billing term is unavailable. Choose another plan to continue.": "រយៈពេលគិតថ្លៃពីមុនមិនអាចប្រើបាន។ ជ្រើសគម្រោងផ្សេងដើម្បីបន្ត។",
  "Choose Reactivate or choose a new plan from the expired Subscription screen.": "ជ្រើសបើកឡើងវិញ ឬជ្រើសគម្រោងថ្មីពីទំព័រគម្រោងជាវផុតកំណត់។",
  "Choose a new billing term to reactivate the subscription.": "ជ្រើសរយៈពេលគិតថ្លៃថ្មីដើម្បីបើកគម្រោងជាវឡើងវិញ។",
  "Unable to verify the latest subscription before reactivation.": "មិនអាចផ្ទៀងផ្ទាត់គម្រោងជាវចុងក្រោយមុនបើកឡើងវិញបានទេ។",
  "Your session expired. Please sign in again.": "វគ្គចូលគណនីផុតកំណត់។ សូមចូលគណនីម្តងទៀត។",
  "Unable to check your existing payment request. Please try again.": "មិនអាចពិនិត្យសំណើទូទាត់ដែលមានស្រាប់បានទេ។ សូមសាកល្បងម្តងទៀត។",
