  "Cancel eligible purchase orders.": "លុបចោលការបញ្ជាទិញចូលដែលអាចធ្វើបាន។",
  "Open inventory pages and stock information.": "បើកទំព័រស្តុក និងព័ត៌មានស្តុក។",
  "Open the activity and audit history.": "បើកប្រវត្តិសកម្មភាព និងសវនកម្ម។",
  "Open, operate and close the assigned branch cash register.": "បើក ប្រើ និងបិទបេឡានៅសាខាដែលបានចាត់តាំង។",
  "Create, edit and manage business branches.": "បង្កើត កែ និងគ្រប់គ្រងសាខាអាជីវកម្ម។",
  "Create and manage stock transfers between allowed branches.": "បង្កើត និងគ្រប់គ្រងការផ្ទេរស្តុករវាងសាខាដែលមានសិទ្ធិ។",
  "Create and manage customer credit transactions.": "បង្កើត និងគ្រប់គ្រងប្រតិបត្តិការឥណទានអតិថិជន។",
  "Use supported export and backup features.": "ប្រើមុខងារនាំចេញ និងបម្រុងទុកដែលគាំទ្រ។",
  "A barcode or SKU is required to print a barcode label.": "ត្រូវមានបាកូដ ឬ SKU ដើម្បីបោះពុម្ពស្លាកបាកូដ។",
  "Code 39 labels require a non-space identifier for POS lookup; the saved value will not be trimmed.": "ស្លាក Code 39 ត្រូវការលេខសម្គាល់ដែលមិនមែនជាចន្លោះសម្រាប់ស្វែងរកក្នុង POS។ តម្លៃដែលបានរក្សាទុកនឹងមិនត្រូវបានកាត់ចន្លោះទេ។",
  "Code 39 labels cannot start or end with whitespace because POS lookup trims scans; the saved value will not be trimmed.": "ស្លាក Code 39 មិនអាចចាប់ផ្តើម ឬបញ្ចប់ដោយចន្លោះទេ ព្រោះ POS កាត់ចន្លោះពេលស្វែងរកកូដស្កេន។ តម្លៃដែលបានរក្សាទុកនឹងមិនត្រូវបានកាត់ចន្លោះទេ។",
  "Code 39 labels support at most 40 characters; the saved value will not be shortened.": "ស្លាក Code 39 គាំទ្រយ៉ាងច្រើន 40 តួអក្សរ។ តម្លៃដែលបានរក្សាទុកនឹងមិនត្រូវបានបង្រួមទេ។",
  "Code 39 labels require uppercase letters; the saved value will not be converted.": "ស្លាក Code 39 ត្រូវការអក្សរធំ។ តម្លៃដែលបានរក្សាទុកនឹងមិនត្រូវបានបម្លែងទេ។",
