  "The variant list changed or a saved row is missing. Reload before saving; use the separate Remove action to remove variants.": "បញ្ជីជម្រើសផលិតផលបានផ្លាស់ប្ដូរ ឬខ្វះជួរទិន្នន័យដែលបានរក្សាទុក។ សូមផ្ទុកម្ដងទៀតមុនពេលរក្សាទុក ហើយប្រើមុខងារដកចេញ ដើម្បីដកជម្រើសផលិតផលចេញ។",
  "This product does not support multiple variants.": "ផលិតផលនេះមិនគាំទ្រជម្រើសផលិតផលច្រើនទេ។",
  "Another user changed this product. Reload and review their changes before saving.": "អ្នកប្រើផ្សេងបានកែប្រែផលិតផលនេះ។ សូមផ្ទុកម្ដងទៀត និងពិនិត្យការផ្លាស់ប្ដូរនោះមុនពេលរក្សាទុក។",
