  "SKU {0} is already used by another product.": "SKU {0} ត្រូវបានប្រើដោយផលិតផលផ្សេងរួចហើយ។",
  "A barcode is already used by another product in this branch.": "បាកូដមួយត្រូវបានប្រើដោយផលិតផលផ្សេងក្នុងសាខានេះរួចហើយ។",
  "Invalid main image action.": "សកម្មភាពលើរូបភាពចម្បងមិនត្រឹមត្រូវ។",
  "Choose an existing image from this product, or upload a new one.": "សូមជ្រើសរើសរូបភាពដែលមានស្រាប់របស់ផលិតផលនេះ ឬបញ្ចូលរូបភាពថ្មី។",
  "Choose the main image again.": "សូមជ្រើសរើសរូបភាពចម្បងម្ដងទៀត។",
