  "You do not have permission to adjust stock.": "អ្នកមិនមានសិទ្ធិកែសម្រួលស្តុកទេ។",
  "Activate and save the selected variants before adjusting stock.": "សូមបើកដំណើរការ និងរក្សាទុកជម្រើសផលិតផលដែលបានជ្រើសរើស មុនពេលកែសម្រួលស្តុក។",
  "Unable to open the stock selection.": "មិនអាចបើកការជ្រើសរើសស្តុកបានទេ។",
  "Save or discard your draft before removing saved variants. This prevents losing other edits.": "សូមរក្សាទុក ឬបោះបង់សេចក្ដីព្រាងមុនពេលដកជម្រើសផលិតផលដែលបានរក្សាទុកចេញ ដើម្បីជៀសវាងការបាត់បង់ការកែប្រែផ្សេងៗ។",
  "Save or discard changes before removing saved rows.": "សូមរក្សាទុក ឬបោះបង់ការកែប្រែមុនពេលដកជួរទិន្នន័យដែលបានរក្សាទុកចេញ។",
