  "Removal could not be confirmed. Reload the product before trying again.": "មិនអាចបញ្ជាក់ការដកចេញបានទេ។ សូមផ្ទុកផលិតផលម្ដងទៀតមុនពេលព្យាយាមឡើងវិញ។",
  "Enter a product name with at least two characters.": "សូមបញ្ចូលឈ្មោះផលិតផលដែលមានយ៉ាងតិចពីរតួអក្សរ។",
  "The save result is uncertain. Reload and review the product before retrying; do not add the variants again.": "លទ្ធផលរក្សាទុកមិនច្បាស់លាស់។ សូមផ្ទុកម្ដងទៀត និងពិនិត្យផលិតផលមុនពេលព្យាយាមឡើងវិញ។ សូមកុំបន្ថែមជម្រើសផលិតផលម្ដងទៀត។",
