  "Remove this image everywhere on this product?": "លុបរូបភាពនេះពីគ្រប់កន្លែងលើផលិតផលនេះ?",
  "Product details, variant edits and image changes will return to the last loaded version. Nothing will be saved.": "ព័ត៌មានផលិតផល ការកែប្រែជម្រើសផលិតផល និងការផ្លាស់ប្ដូររូបភាព នឹងត្រឡប់ទៅកំណែដែលបានផ្ទុកចុងក្រោយ។ មិនមានអ្វីត្រូវបានរក្សាទុកទេ។",
  "Saved rows are removed from the current branch immediately after confirmation, not on Save. Remaining stock in this branch is set to zero and recorded in the stock ledger within the same database operation. Historical records and other branches are kept. Choose Hide instead to keep the rows visible here.": "ជួរទិន្នន័យដែលបានរក្សាទុកនឹងត្រូវដកចេញពីសាខាបច្ចុប្បន្នភ្លាមៗបន្ទាប់ពីបញ្ជាក់ ដោយមិនចាំបាច់ចុចរក្សាទុក។ ស្តុកនៅសល់ក្នុងសាខានេះត្រូវបានកំណត់ជា 0 និងកត់ត្រាក្នុងបញ្ជីស្តុក ក្នុងប្រតិបត្តិការទិន្នន័យតែមួយ។ ប្រវត្តិ និងសាខាផ្សេងត្រូវបានរក្សាទុក។ ជ្រើសរើសលាក់ ដើម្បីទុកជួរទិន្នន័យនៅទីនេះ។",
  "The main image and every variant image will be cleared in this draft. Save to apply, or Discard to undo. Stored files are kept.": "រូបភាពចម្បង និងរូបភាពជម្រើសផលិតផលទាំងអស់នឹងត្រូវសម្អាតក្នុងសេចក្ដីព្រាងនេះ។ ចុចរក្សាទុកដើម្បីអនុវត្ត ឬបោះបង់ដើម្បីត្រឡប់វិញ។ ឯកសារដែលបានរក្សាទុកនៅតែមាន។",
  "This removes the image from the main image and every variant using it in this draft. Unaffected images stay. Save to apply, or Discard to undo.": "រូបភាពនេះនឹងត្រូវដកចេញពីរូបភាពចម្បង និងគ្រប់ជម្រើសផលិតផលដែលប្រើវាក្នុងសេចក្ដីព្រាងនេះ។ រូបភាពផ្សេងនៅតែមាន។ ចុចរក្សាទុកដើម្បីអនុវត្ត ឬបោះបង់ដើម្បីត្រឡប់វិញ។",
