  "Subscription upgrade is not ready. Apply the latest TENH POS subscription migrations, then reopen Plans. Your existing subscription is unchanged.": "ការដំឡើងគម្រោងជាវមិនទាន់រួចរាល់។ អនុវត្តការធ្វើបច្ចុប្បន្នភាពរចនាសម្ព័ន្ធគម្រោងជាវ TENH POS ចុងក្រោយ រួចបើកគម្រោងឡើងវិញ។ គម្រោងជាវដែលមានស្រាប់នៅដដែល។",
